                            <div class="pop" id="sortPop"><a href="?sort=name_asc" class="<?= $sort === 'name_asc' ? 'active' : '' ?>">Name (A-Z)</a><a href="?sort=name_desc" class="<?= $sort === 'name_desc' ? 'active' : '' ?>">Name (Z-A)</a><a href="?sort=price_asc" class="<?= $sort === 'price_asc' ? 'active' : '' ?>">Price (low to high)</a><a href="?sort=price_desc" class="<?= $sort === 'price_desc' ? 'active' : '' ?>">Price (high to low)</a><a href="?sort=stock_asc" class="<?= $sort === 'stock_asc' ? 'active' : '' ?>">Stock (low to high)</a><a href="?sort=stock_desc" class="<?= $sort === 'stock_desc' ? 'active' : '' ?>">Stock (high to low)</a></div>
                        </div>
                    </div>
                    <div class="table-responsive">
                        <table id="productsTable">
                            <thead>
                                <tr><th><a href="?sort=<?= $sort === 'name_asc' ? 'name_desc' : 'name_asc' ?>">Product Name</a></th><th><a href="?sort=<?= $sort === 'price_asc' ? 'price_desc' : 'price_asc' ?>">Price</a></th><th><a href="?sort=<?= $sort === 'stock_asc' ? 'stock_desc' : 'stock_asc' ?>">Current Stock</a></th><th>Reorder Level</th><th>Status</th><th>Last Updated</th><th>Action</th></tr>
                            </thead>
                            <tbody>
                                <?php if ($products->num_rows > 0): while ($row = $products->fetch_assoc()): ?>
                                    <?php
                                        $daysLeft = null; $expiryText = ''; $expiryColor = '';
                                        if (!empty($row['expiry_date'])) {
                                            $expiry = new DateTime($row['expiry_date']); $today  = new DateTime(date('Y-m-d'));
                                            $daysLeft = (int)$today->diff($expiry)->format('%r%a');
                                            if ($daysLeft < 0) { $expiryColor = '#dc2626'; $expiryText = 'EXPIRED (' . abs($daysLeft) . ' days ago)'; }
                                            elseif ($daysLeft <= 3) { $expiryColor = '#b45309'; $expiryText = 'Expires ' . $expiry->format('M d, Y') . ' (' . $daysLeft . ' days left)'; }
                                            else { $expiryColor = '#15803d'; $expiryText = 'Expires ' . $expiry->format('M d, Y') . ' (' . $daysLeft . ' days left)'; }
                                        }
                                        $isExpired = ($row['status'] === 'expired') || ($daysLeft !== null && $daysLeft < 0); $stock = (int)$row['stock_quantity'];
                                        if ($stock <= 0) { $statusLabel = 'Out of Stock'; $statusClass = 'out-of-stock'; }
                                        elseif ($isExpired) { $statusLabel = 'Expired'; $statusClass = 'expired'; }
                                        elseif ($stock <= (int)$row['reorder_level']) { $statusLabel = 'Low Stock'; $statusClass = 'low-stock'; }
                                        else { $statusLabel = 'In Stock'; $statusClass = 'in-stock'; }
                                        $updatedRaw = $row['updated_at'] ?? $row['last_updated'] ?? $row['created_at'] ?? null; $updatedTs  = $updatedRaw ? strtotime($updatedRaw) : false;
                                        $isHighlighted = isset($_SESSION['highlight_products']) && in_array($row['product_id'], $_SESSION['highlight_products']); $rowStyle = $isHighlighted ? "style='background-color:#fef3c7;'" : "";
                                    ?>
                                    <tr <?= $rowStyle ?> data-status="<?= $statusClass ?>" data-search="<?= htmlspecialchars(strtolower($row['name'] . ' ' . $row['sku'] . ' ' . ($row['description'] ?? ''))) ?>">
                                        <td title="<?= htmlspecialchars('SKU: ' . $row['sku'] . (!empty($row['description']) ? ' - ' . $row['description'] : '')) ?>"><div class="product-name"><?= htmlspecialchars($row['name']) ?></div><?php if ($daysLeft !== null && $daysLeft <= 3): ?><div style="font-size: 10px; font-weight: 700; color: <?= $expiryColor ?>; margin-top: 2px;"><?= htmlspecialchars($expiryText) ?></div><?php endif; ?></td>
                                        <td class="price">&#8369; <?= number_format($row['unit_price'], 0) ?></td>
                                        <td><?= $stock ?></td>
                                        <td><?= (int)$row['reorder_level'] ?></td>
                                        <td><span class="status <?= $statusClass ?>"><?= $statusLabel ?></span></td>
                                        <td class="updated"><?php if ($updatedTs): ?><?= date('F d, Y', $updatedTs) ?><br><?= date('g:i A', $updatedTs) ?><?php else: ?>&mdash;<?php endif; ?></td>
                                        <td class="actions-cell">
                                            <div class="actions">
                                                <?php if ($is_store_open): ?>
                                                    <button class="btn-edit" disabled>Edit</button><button class="btn-delete" disabled>Delete</button>
                                                <?php else: ?>
                                                    <button class="btn-edit" onclick='openProductModal(<?= json_encode($row) ?>)'>Edit</button><button class="btn-delete" onclick='openDeleteModal(<?= $row['product_id'] ?>, <?= json_encode($row['name']) ?>)'>Delete</button>
                                                <?php endif; ?>
                                            </div>
                                        </td>
                                    </tr>
                                <?php endwhile; else: ?>
                                    <tr><td colspan="7" style="text-align:center;">No products found</td></tr>
                                <?php endif; ?>
                                <tr id="noMatchRow" style="display:none;"><td colspan="7" style="text-align:center; color:#888;">No matching products</td></tr>
                            </tbody>
                        </table>
                    </div>
                    <?php if ($total_pages > 1): ?>
                    <div class="pagination">
                        <?php if ($page > 1): ?><a href="?sort=<?= $sort ?>&page=<?= $page - 1 ?>">Prev</a><?php else: ?><span class="disabled">Prev</span><?php endif; ?>
                        <?php for ($i = 1; $i <= $total_pages; $i++): ?><?php if ($i === $page): ?><span class="active"><?= $i ?></span><?php else: ?><a href="?sort=<?= $sort ?>&page=<?= $i ?>"><?= $i ?></a><?php endif; ?><?php endfor; ?>
                        <?php if ($page < $total_pages): ?><a href="?sort=<?= $sort ?>&page=<?= $page + 1 ?>">Next</a><?php else: ?><span class="disabled">Next</span><?php endif; ?>
                    </div>
                    <?php endif; ?>
                </section>
            </main>
        </div>
    </div>

    <dialog id="productModal">
        <h2 id="modalTitle">Add Product</h2>
        <form method="POST">
            <?= csrf_field() ?><input type="hidden" name="product_id" id="form_id" value="">
            <label>Product Name</label><input type="text" name="name" id="form_name" maxlength="50" required>
            <label style="margin-top: 15px;">Shelf Life (Days)</label><input type="number" min="1" name="shelf_life_days" id="form_shelf_life" value="30" required>
            <label>Description</label><textarea name="description" id="form_description" maxlength="255" rows="2" placeholder="Brief description..." style="width: 100%; padding: 10px; border: 1px solid #ddd; border-radius: 8px; margin-bottom: 15px; resize: vertical; font-family: inherit;"></textarea>
            <div class="row"><div><label>Price (&#8369;)</label><input type="number" step="0.01" min="0" name="unit_price" id="form_price" required></div><div><label>Reorder Level</label><input type="number" min="1" name="reorder_level" id="form_reorder" required></div></div>
            <label>Stock Quantity</label><input type="number" min="0" name="stock_quantity" id="form_stock" required>
            <div class="dialog-buttons"><button type="button" class="cancel-btn" onclick="closeProductModal()">Cancel</button><button type="submit" name="save_product" class="primary-btn">Save Product</button></div>
        </form>
    </dialog>

    <dialog id="deleteModal">
        <h2 style="color: #dc2626; margin-bottom: 10px;">Confirm Deletion</h2>
        <p style="margin-bottom: 20px; font-size: 14px; color: #555;">Are you sure you want to permanently delete <strong id="deleteProductName"></strong>? This action cannot be undone.</p>
        <form method="POST" id="deleteForm">
            <?= csrf_field() ?><input type="hidden" name="product_id" id="delete_product_id" value="">
            <div class="dialog-buttons"><button type="button" class="cancel-btn" onclick="closeDeleteModal()">Cancel</button><button type="submit" name="delete_product" style="padding: 10px 20px; background: #dc2626; color: white; border: none; border-radius: 8px; cursor: pointer; font-weight: bold;">Yes, Delete</button></div>
        </form>
    </dialog>

    <dialog id="importModal">
        <h2 style="margin-top:0;">Import Products (CSV)</h2>
        <p style="font-size: 13px; color: #555; margin-bottom: 15px;">Upload a CSV to bulk-add or update. Required columns: <code>product_id, name, description, sku, unit_price, stock_quantity, reorder_level, status</code>.</p>
        <form action="/php-web/public/products/import-csv" method="POST" enctype="multipart/form-data">
            <?= csrf_field() ?><input type="file" name="csv_file" accept=".csv" required style="width:100%; padding:10px; border:1px solid #ddd; border-radius:8px; margin-bottom:20px;">
            <div style="display: flex; justify-content: flex-end; gap: 10px;"><button type="button" onclick="document.getElementById('importModal').close()" style="padding: 10px 20px; background: #eee; border: none; border-radius: 8px; font-weight: bold; cursor: pointer;">Cancel</button><button type="submit" name="import_csv" style="padding: 10px 20px; background: #333; color: white; border: none; border-radius: 8px; font-weight: bold; cursor: pointer;">Upload CSV</button></div>
        </form>
    </dialog>
    <?php unset($_SESSION['highlight_products']); ?>

    <script>
        function closePops() { document.querySelectorAll('.pop.show').forEach(p => p.classList.remove('show')); }
        function togglePop(event, id) {
            event.stopPropagation();
            const prof = document.getElementById('profileDropdown');
            if (prof) prof.classList.remove('show');
            const notif = document.getElementById('notifDropdown');
            if (notif) notif.classList.remove('show');
            
            const pop = document.getElementById(id);
            if (!pop) return;
            const wasOpen = pop.classList.contains('show');
            document.querySelectorAll('.pop').forEach(p => p.classList.remove('show'));
            if (!wasOpen) pop.classList.add('show');
        }
        document.addEventListener('click', function(event) { if (!event.target.closest('.menu-wrap')) closePops(); });
        let activeFilter = 'all';
        function applyTableFilters() {
            const q = document.getElementById('productSearch').value.trim().toLowerCase(); const rows = document.querySelectorAll('#productsTable tbody tr[data-status]'); let visible = 0;
            rows.forEach(tr => { const matchSearch = !q || tr.dataset.search.includes(q); const matchStatus = activeFilter === 'all' || tr.dataset.status === activeFilter; const show = matchSearch && matchStatus; tr.style.display = show ? '' : 'none'; if (show) visible++; });
            const noMatch = document.getElementById('noMatchRow'); if (noMatch) noMatch.style.display = (rows.length && !visible) ? '' : 'none';
        }
        document.getElementById('productSearch').addEventListener('input', applyTableFilters);
        document.querySelectorAll('#filterPop [data-filter]').forEach(btn => { btn.addEventListener('click', function() { activeFilter = this.dataset.filter; document.querySelectorAll('#filterPop [data-filter]').forEach(b => b.classList.remove('active')); this.classList.add('active'); applyTableFilters(); closePops(); }); });
        function openProductModal(product = null) {
            const modal = document.getElementById('productModal');
            if (product) {
                document.getElementById('modalTitle').textContent = 'Edit Product'; document.getElementById('form_id').value = product.product_id; document.getElementById('form_name').value = product.name; document.getElementById('form_description').value = product.description || ''; document.getElementById('form_price').value = product.unit_price; document.getElementById('form_reorder').value = product.reorder_level; document.getElementById('form_stock').value = product.stock_quantity; document.getElementById('form_shelf_life').value = product.shelf_life_days || 30;
            } else {
                document.getElementById('modalTitle').textContent = 'Add Product'; document.getElementById('form_id').value = ''; document.getElementById('form_name').value = ''; document.getElementById('form_description').value = ''; document.getElementById('form_price').value = ''; document.getElementById('form_reorder').value = ''; document.getElementById('form_stock').value = ''; document.getElementById('form_shelf_life').value = 30;
            }
            modal.showModal();
        }
        function closeProductModal() { document.getElementById('productModal').close(); }
        function openDeleteModal(id, name) { document.getElementById('delete_product_id').value = id; document.getElementById('deleteProductName').textContent = name; document.getElementById('deleteModal').showModal(); }
        function closeDeleteModal() { document.getElementById('deleteModal').close(); }
        function toggleProfileMenu(event) {
            event.stopPropagation();
            const notif = document.getElementById('notifDropdown');
            if (notif) notif.classList.remove('show');
            document.querySelectorAll('.pop').forEach(p => p.classList.remove('show'));
            const prof = document.getElementById('profileDropdown');
            if (prof) prof.classList.toggle('show');
        }
        document.addEventListener('click', function(event) { const menu = document.getElementById('profileMenu'); if (menu && !menu.contains(event.target)) document.getElementById('profileDropdown').classList.remove('show'); });
        function toggleNotifications(event) {
            event.stopPropagation();
            const prof = document.getElementById('profileDropdown');
            if (prof) prof.classList.remove('show');
            document.querySelectorAll('.pop').forEach(p => p.classList.remove('show'));
            const notif = document.getElementById('notifDropdown');
            if (notif) notif.classList.toggle('show');
        }
        document.addEventListener('click', function(event) { const container = document.getElementById('notifContainer'); const dropdown = document.getElementById('notifDropdown'); if (container && !container.contains(event.target)) { if(dropdown) dropdown.classList.remove('show'); } });
        let lastNotifCount = 0;
        function playBeep() { try { let context = new (window.AudioContext || window.webkitAudioContext)(); let osc = context.createOscillator(); osc.type = 'sine'; osc.frequency.value = 800; osc.connect(context.destination); osc.start(); osc.stop(context.currentTime + 0.15); } catch (e) {} }
        function checkNotifications() {
            fetch('/php-web/public/notifications', { credentials: 'same-origin' }).then(response => response.json()).then(data => {
                const badge = document.getElementById('notif-badge'); const list = document.getElementById('notifList');
                if (badge && list) {
                    let readIds = JSON.parse(localStorage.getItem('readNotifIds') || '[]'); let unreadCount = 0;
                    data.orders.forEach(item => { const itemId = item.type === 'order' ? 'order-' + item.order_id : 'log-' + item.log_id; if (!readIds.includes(itemId)) unreadCount++; });
                    if (unreadCount > 0) { badge.style.display = 'flex'; badge.textContent = unreadCount; if (unreadCount > lastNotifCount) playBeep(); } else { badge.style.display = 'none'; }
                    lastNotifCount = unreadCount; list.innerHTML = '';
                    data.orders.forEach(item => {
                        const date = new Date(item.type === 'order' ? item.order_date : item.timestamp); const timeAgo = date.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
                        const itemId = item.type === 'order' ? 'order-' + item.order_id : 'log-' + item.log_id; const isRead = readIds.includes(itemId); const readStyle = isRead ? 'opacity: 0.6;' : '';
                        if (item.type === 'order') { list.innerHTML += `<a href="/php-web/public/orders/view?id=${item.order_id}" class="notif-item" style="${readStyle}" data-notif-id="${itemId}" onclick="markAsRead('${itemId}')"><div class="notif-icon">#${item.order_id}</div><div class="notif-content"><p><strong>${item.retailer_name}</strong> placed a new order.</p><span class="notif-time">${timeAgo} &middot; &#8369;${Number(item.total_amount).toFixed(2)}</span></div></a>`; }
                        else { list.innerHTML += `<a href="/php-web/public/drivers?search=${encodeURIComponent(item.driver_name)}" class="notif-item" style="${readStyle}" data-notif-id="${itemId}" onclick="markAsRead('${itemId}')"><div class="notif-icon" style="background: #15803d; border-radius: 50%;"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></div><div class="notif-content"><p>${item.action}</p><span class="notif-time">${timeAgo} &middot; Click to view driver</span></div></a>`; }
                    });
                }
            }).catch(err => console.error('Error fetching notifications:', err));
        }
        function markAsRead(itemId) { let readIds = JSON.parse(localStorage.getItem('readNotifIds') || '[]'); if (!readIds.includes(itemId)) { readIds.push(itemId); localStorage.setItem('readNotifIds', JSON.stringify(readIds)); } }
        checkNotifications(); setInterval(checkNotifications, 15000);
        if (sessionStorage.getItem('scrollPos')) document.documentElement.style.visibility = 'hidden';
        window.addEventListener('load', function() { const savedPosition = sessionStorage.getItem('scrollPos'); if (savedPosition) { window.scrollTo(0, parseInt(savedPosition)); document.documentElement.style.visibility = 'visible'; sessionStorage.removeItem('scrollPos'); } });
        document.addEventListener('mousedown', function(event) { if (event.target.closest('th a') || event.target.closest('.pagination a') || event.target.closest('#sortPop a') || event.target.closest('button[type="submit"]')) { sessionStorage.setItem('scrollPos', window.scrollY); } });
            
        // Close all when clicking outside
        document.addEventListener('click', function(event) {
            const menu = document.getElementById('profileMenu');
            if (menu && !menu.contains(event.target)) {
                const prof = document.getElementById('profileDropdown');
                if (prof) prof.classList.remove('show');
            }
            const c = document.getElementById('notifContainer');
            if (c && !c.contains(event.target)) {
                const d = document.getElementById('notifDropdown');
                if (d) d.classList.remove('show');
            }
            if (!event.target.closest('.menu-wrap')) {
                document.querySelectorAll('.pop').forEach(p => p.classList.remove('show'));
            }
        });
    </script>
</body>
</html>








